UPDATE block_definitions
SET template = '<section id="comments" class="stratum-comments">{{ if .Context.CommentsCount }}<h2 class="stratum-comments-title">Comments ({{ .Context.CommentsCount }})</h2>{{ else }}<h2 class="stratum-comments-title">Comments</h2>{{ end }}<div id="comment-list">{{ if .Context.Comments }}{{ range .Context.Comments }}<article class="stratum-comment comment-depth-{{ .Depth }}" id="comment-{{ .ID }}"><header class="stratum-comment-header"><span class="stratum-comment-author">{{ .AuthorName }}</span> <time datetime="{{ .CreatedISO }}">{{ .CreatedAt }}</time>{{ if .ParentID }} <a href="#comment-{{ .ParentID }}">in reply</a>{{ end }}</header><div class="stratum-comment-body">{{ .Body }}</div></article>{{ end }}{{ else }}<p class="stratum-comments-empty">No comments yet. Be the first to comment.</p>{{ end }}</div>{{ if .Context.CommentsEnabled }}<form id="comment-form" method="post" action="/comments" class="stratum-comment-form" data-on:submit__prevent="@post(''/comments'', {contentType: ''form''})"><input type="hidden" name="entry_id" value="{{ .Context.CommentsEntryID }}"><input type="hidden" name="parent_id" value=""><div id="comment-form-errors"></div><div class="stratum-comment-field"><label for="comment-author-name">Name</label><input id="comment-author-name" name="author_name" required maxlength="100"></div><div class="stratum-comment-field"><label for="comment-author-email">Email</label><input id="comment-author-email" name="author_email" type="email" required maxlength="254"></div><div class="stratum-comment-field"><label for="comment-author-url">Website (optional)</label><input id="comment-author-url" name="author_url" type="url" maxlength="2048"></div><p class="stratum-comment-honeypot"><label for="comment-website-confirm">Leave empty</label><input id="comment-website-confirm" name="website_confirm" autocomplete="off" tabindex="-1"></p><div class="stratum-comment-field"><label for="comment-body">Comment</label><textarea id="comment-body" name="body" required maxlength="5000"></textarea></div><div class="stratum-comment-actions"><button type="submit">Post Comment</button></div><div id="comment-submit-status"></div></form>{{ else }}<p class="stratum-comments-disabled">Comments are closed.</p>{{ end }}</section>',
    styles = '.stratum-comments{max-width:var(--st-prose-width, 720px);width:100%;margin-top:var(--st-space-xl)}.stratum-comments-title{font-family:var(--st-font-heading);font-weight:var(--st-heading-weight);color:var(--st-color-heading);font-size:var(--st-h3-size, 1.35rem);line-height:1.25;margin:0 0 var(--st-space-md);letter-spacing:-0.01em}.stratum-comments-empty,.stratum-comments-disabled{color:var(--st-color-text-muted);font-size:var(--st-small-size, 0.9rem);line-height:1.6;padding:var(--st-space-md) 0;border-top:1px solid var(--st-color-border)}.stratum-comment{border-top:1px solid var(--st-color-border);padding:var(--st-space-md) 0}.stratum-comment-header{display:flex;flex-wrap:wrap;align-items:baseline;gap:var(--st-space-xs) var(--st-space-md);font-size:var(--st-small-size, 0.85rem);margin-bottom:var(--st-space-xs)}.stratum-comment-author{font-weight:600;color:var(--st-color-heading);font-size:0.95rem}.stratum-comment-header time{color:var(--st-color-text-muted)}.stratum-comment-header a{color:var(--st-color-text-muted);text-decoration:none}.stratum-comment-header a:hover{color:var(--st-link-color);text-decoration:underline}.stratum-comment-body{white-space:pre-wrap;word-wrap:break-word;overflow-wrap:break-word;color:var(--st-color-text);line-height:1.65;font-size:var(--st-body-size, 1rem);max-width:65ch}.comment-depth-1{margin-left:1.25rem}.comment-depth-2{margin-left:2.5rem}.stratum-comment-honeypot{position:absolute!important;width:1px!important;height:1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important}.stratum-comment-form{display:grid;gap:var(--st-space-md);width:100%;max-width:var(--st-prose-width, 720px);margin-top:var(--st-space-xl);padding-top:var(--st-space-xl);border-top:1px solid var(--st-color-border)}.stratum-comment-field{display:grid;gap:var(--st-space-xs)}.stratum-comment-field label{font-weight:500;font-size:var(--st-small-size, 0.9rem);color:var(--st-color-text)}.stratum-comment-form input:not([type=hidden]),.stratum-comment-form textarea{width:100%;box-sizing:border-box;padding:var(--st-space-sm);color:var(--st-color-text);background:var(--st-color-background, #fff);border:1px solid var(--st-color-border);border-radius:var(--st-radius-sm, 6px);font:inherit;font-size:var(--st-body-size, 1rem);line-height:1.5}.stratum-comment-form textarea{min-height:9rem;resize:vertical;line-height:1.6}.stratum-comment-form input:focus-visible,.stratum-comment-form textarea:focus-visible{outline:3px solid var(--st-color-focus);outline-offset:2px;border-color:var(--st-color-focus)}.stratum-comment-form button[type=submit]{display:inline-flex;align-items:center;justify-content:center;min-height:42px;padding:var(--st-button-padding-y, 0.6rem) var(--st-button-padding-x, 1rem);background:var(--st-color-primary);color:var(--st-color-primary-contrast);border:2px solid transparent;border-radius:var(--st-button-radius, var(--st-radius-sm, 6px));font-weight:var(--st-button-font-weight, 600);font-size:0.95rem;line-height:1.2;cursor:pointer;transition:background-color 0.15s ease}.stratum-comment-form button[type=submit]:hover{background:var(--st-color-primary-hover)}.stratum-comment-form button[type=submit]:focus-visible{outline:3px solid var(--st-color-focus);outline-offset:2px}.stratum-comment-actions{margin-top:var(--st-space-xs)}#comment-form-errors .form-error{color:#8a1c1c;background:color-mix(in srgb, #fee 85%, white);border:1px solid #f0c2c2;border-radius:var(--st-radius-sm, 6px);padding:var(--st-space-sm) var(--st-space-md);font-size:var(--st-small-size, 0.9rem)}#comment-submit-status .success{color:var(--st-color-text);background:var(--st-color-surface-muted, #f6f6f6);border:1px solid var(--st-color-border);border-radius:var(--st-radius-sm, 6px);padding:var(--st-space-sm) var(--st-space-md);font-size:var(--st-small-size, 0.9rem)}'
WHERE namespace = 'core' AND name = 'comments' AND version = 1;
